import json,shutil,argparse
from pathlib import Path
from PIL import Image,ImageOps
parser=argparse.ArgumentParser(description='Pack and install approved Transit enemy exports. Requires Pillow.')
parser.add_argument('--project-root',type=Path,default=Path(__file__).resolve().parents[2])
parser.add_argument('--art-root',type=Path)
args=parser.parse_args();P=args.art_root or args.project_root/'.tools/gamedev/transit-enemies';data=json.loads((P/'export/manifest.json').read_text());out=args.project_root/'Assets/Game/Resources/Detailed/TransitEnemies'

for id,info in data.items():
 src=P/'export'/id;dest=out/'Textures'/id;dest.mkdir(parents=True,exist_ok=True);(out/'Models').mkdir(exist_ok=True);shutil.copy2(src/(id+'.fbx'),out/'Models'/(id+'.fbx'))
 for m in info['materials']:
  rough=Image.open(src/m['maps']['Roughness']).convert('L');metal=Image.open(src/m['maps']['Metallic']).convert('L').resize(rough.size);zero=Image.new('L',rough.size,0);Image.merge('RGBA',(metal,zero,zero,ImageOps.invert(rough))).save(dest/(m['id']+'_MetalSmooth.png'))
  for file in m['maps'].values():shutil.copy2(src/file,dest/file)
(out/'manifest.json').write_text(json.dumps(data,indent=2))
credits='# Transit enemy credits\n\nAll sources CC BY 4.0: https://creativecommons.org/licenses/by/4.0/ .\n\n'
for x in json.loads((P/'sources.json').read_text()):
 if x['role']=='Boss':continue
 credits+=f"- {x['role']}: {x['author']} — {x['source']}. Original archive SHA256 `{x['sha256']}`.\n"
credits+='\nDefender rifle: Sci-Fi Rifle by ul1tka, CC BY 4.0: https://sketchfab.com/3d-models/sci-fi-rifle-648a72a0046a4d059cd850f32f30f4ce .\n\nChanges: original model geometry/UVs/PBR detail retained; source skeletons rebased to reviewed equipment poses; added payload and shield/rifle equipment retained; drone receives a two-bone mechanical rig; meshes combined by asset into one skin with material submeshes. Texture channels baked to Unity Standard, metallic R/smoothness A; maps capped at 2K. Forty-four authored in-place gameplay clips are generated by BiomeCombatClips. These are not a complete reuse of source animation libraries, motion capture or foot IK.\n\nApproved proportions retained: payload/hull lateral center aligned, riot rifle enlarged 1.45x around hand grip to 1.3775m for a 2.25m unit. Optional Yellow Heavy Robot remains a local preview and is not shipped by this integration. Rebuild with TransitEnemyAssets.Build; builds need no Blender or downloads. See docs/TRANSIT_BIOME.md and Tools/Art/export_transit_enemies.py.\n'
(out/'CREDITS.md').write_text(credits)
print('INSTALLED',[(k,v['triangles'],v['bones']) for k,v in data.items()])
